import{createCube,parseAlg,inverse,move,apply,drawCube}from './cube.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const storage={get(k,f){try{return JSON.parse(localStorage.getItem('fangcun-'+k))??f}catch{return f}},set(k,v){try{localStorage.setItem('fangcun-'+k,JSON.stringify(v))}catch{toast('当前浏览器无法保存记录')}}};
let favorites=new Set(storage.get('favorites',[])),progress=storage.get('progress',{}),times=storage.get('times',[]),data=[],page=0,category='cfop';
const groupNames={F2L:'F2L · 前两层配对',OLL:'OLL · 顶层定向（57）',PLL:'PLL · 顶层排列（21）',COLL:'COLL · 顶层角块',CMLL:'CMLL · Roux 角块', '2LOLL':'二步 OLL','2LPLL':'二步 PLL','2AOLL':'入门 OLL · 2 个核心公式','2APLL':'入门 PLL · 2 个核心公式','4AOLL':'基础 OLL · 4 个核心公式','4APLL':'基础 PLL · 4 个核心公式',PBL:'PBL · 二阶双层排列',L2E:'L2E · 五阶最后两组棱',L3E:'L3E · 金字塔最后三棱',L4E:'L4E · 金字塔最后四棱',PARITY:'四阶 · 特殊情况'};
const categories={cfop:['F2L','OLL','PLL'],beginner:['2LOLL','2LPLL','2AOLL','2APLL','4AOLL','4APLL'],roux:['CMLL','COLL'],two:['PBL'],big:['PARITY','L2E'],pyraminx:['L3E','L4E']};
const catNames={cfop:'CFOP',beginner:'入门公式',roux:'Roux / COLL',two:'二阶',big:'高阶',pyraminx:'金字塔'};
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function saveFav(){storage.set('favorites',[...favorites]);$('#favCount').textContent=favorites.size}
saveFav();
function switchCategory(c){category=c;page=0;$('#tabs').innerHTML=Object.keys(categories).map(k=>`<button data-cat="${k}" class="${k===c?'active':''}">${catNames[k]}</button>`).join('');$('#groupSelect').innerHTML=categories[c].map(g=>`<option value="${g}">${groupNames[g]}</option>`).join('');renderCards()}
function filtered(){const q=$('#search').value.trim().toLowerCase(),g=$('#groupSelect').value;return data.filter(d=>d.group===g&&(!$('#onlyFav').checked||favorites.has(d.id))&&(!q||[d.group,d.name,d.label,...d.algs].join(' ').toLowerCase().includes(q)))}
function puzzleSize(d){return d.group==='PBL'?2:d.group==='PARITY'?4:d.group==='L2E'?5:3}
function isPyraminx(d){return ['L3E','L4E'].includes(d.group)}
function renderCards(){const items=filtered(),max=Math.max(1,Math.ceil(items.length/8));page=Math.min(page,max-1);$('#resultCount').textContent=items.length+' 个局面';$('#algGrid').innerHTML='';for(const d of items.slice(page*8,page*8+8)){const card=document.createElement('article');card.className='alg-card';const favorite=document.createElement('button');favorite.className='favorite'+(favorites.has(d.id)?' saved':'');favorite.textContent=favorites.has(d.id)?'♥':'♡';favorite.setAttribute('aria-label','收藏 '+d.group+' '+d.name);favorite.onclick=()=>{favorites.has(d.id)?favorites.delete(d.id):favorites.add(d.id);saveFav();renderCards()};card.append(favorite);const top=document.createElement('span');top.className='case-top';top.textContent=d.group+' / CASE '+String(d.name).padStart(2,'0');card.append(top);const canvas=document.createElement('canvas');canvas.className='case-canvas';canvas.width=180;canvas.height=180;card.append(canvas);if(!isPyraminx(d)){try{const size=puzzleSize(d),state=apply(createCube(size),inverse(parseAlg(d.algs[0])),size);drawCube(canvas,state,size,-.55,.85)}catch{canvas.style.display='none'}}else{const ctx=canvas.getContext('2d');ctx.fillStyle='#d9e5c3';ctx.beginPath();ctx.moveTo(90,20);ctx.lineTo(22,143);ctx.lineTo(158,143);ctx.closePath();ctx.fill();ctx.fillStyle='#889a72';ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText('Pyraminx',90,167);canvas.setAttribute('aria-label','金字塔魔方类别示意图，不是局面图')}
const h=document.createElement('h3');h.textContent=d.group+' '+d.name;card.append(h);const p=document.createElement('div');p.className='case-label';p.textContent=d.label;card.append(p);const formula=document.createElement('div');formula.className='formula';formula.textContent=d.algs[0];card.append(formula);const see=document.createElement('button');see.className='see';see.innerHTML='<span>查看公式'+(isPyraminx(d)?'':'与演示')+'</span><span>↗</span>';see.onclick=()=>showAlg(d);card.append(see);$('#algGrid').append(card)}if(!items.length)$('#algGrid').innerHTML='<p class="empty">还没找到这条公式，换个关键词，或先收藏一个喜欢的局面吧 ♡</p>';$('#pageLabel').textContent=(page+1)+' / '+max;$('#prev').disabled=page===0;$('#next').disabled=page>=max-1;}
$('#tabs').onclick=e=>{if(e.target.dataset.cat)switchCategory(e.target.dataset.cat)};$('#groupSelect').onchange=$('#search').oninput=$('#onlyFav').onchange=()=>{page=0;renderCards()};$('#prev').onclick=()=>{page--;renderCards()};$('#next').onclick=()=>{page++;renderCards()};$('#favorites').onclick=()=>{const d=data.find(d=>favorites.has(d.id));if(d){switchCategory(Object.keys(categories).find(k=>categories[k].includes(d.group)));$('#groupSelect').value=d.group}$('#onlyFav').checked=true;renderCards();$('#library').scrollIntoView({behavior:'smooth'});toast('切换分类可以查看不同方法的收藏')};
function showAlg(d){$('#algTitle').textContent=d.group+' '+d.name;$('#algDesc').textContent=groupNames[d.group]+' · '+d.label;$('#algOptions').innerHTML='';d.algs.forEach((alg,i)=>{const wrap=document.createElement('div');wrap.className='alg-option';const p=document.createElement('p');p.className='formula';p.textContent=alg;wrap.append(p);const copy=document.createElement('button');copy.className='outline';copy.textContent='复制公式';copy.onclick=async()=>{try{await navigator.clipboard.writeText(alg);toast('公式已放进口袋 ♡')}catch{toast('请选中公式文字复制')}};wrap.append(copy);if(!isPyraminx(d)){const play=document.createElement('button');play.className='primary';play.style.marginLeft='10px';play.textContent='逐步演示 →';play.onclick=()=>{try{const tokens=parseAlg(alg);size=puzzleSize(d);$('#puzzle').value=String(size);stopSequence();state=apply(createCube(size),inverse(tokens),size);history=[];sequence=tokens;seqIndex=0;$('#algInput').value=alg;$('#scrambleText').textContent=d.group+' '+d.name+' · 从当前局面逐步还原';draw();updateSequence();$('#algDialog').close();$('#play').scrollIntoView({behavior:'smooth'});toast('点击下一步，或再次点击播放开始自动演示')}catch(e){toast(e.message)}};wrap.append(play)}else{const note=document.createElement('p');note.textContent='金字塔公式可查阅和收藏；当前互动演示支持立方体魔方。';wrap.append(note)}$('#algOptions').append(wrap)});$('#algDialog').showModal()}
const courses={beginner:{title:'第一次还原 · 三阶七步小旅程',intro:'先认识三种块：中心块决定面色；棱块有两色；角块有三色。下面始终保持白色在底、黄色在顶。每一步都检查侧面颜色，不能只看单面。',lessons:[['白色十字','先把四个白色棱块放在黄色中心周围做“小花”。依次转 U，使白棱侧色对齐相同颜色的中心，再将该面转 180°，把白棱送到底面。检查底面白十字，同时四个侧色都要对齐。','F2'],['白色角块','找到一个白角，放到它对应槽位的正上方（右前上）。用右手小循环直到白角归位。若角块在底层但放错，先用同一循环取出，再调整顶层。每次只处理一个白角。',"R U R' U'"],['中层棱块','在顶层找到不含黄色的棱块，让前面颜色对齐中心。另一色若属于右面，执行右插公式；若属于左面，执行左插公式。中层棱放错时，用公式先换出。右插：U R U\' R\' U\' F\' U F；左插：U\' L\' U L U F U\' F\'。',"U R U' R' U' F' U F"],['黄色十字','只观察顶层四条棱的朝向。横线放水平；L 形的两条黄棱指向后面和左面。执行公式后重新观察；点形先执行一次，再按新图案摆放。角块此时不用管。',"F R U R' U' F'"],['黄色角块位置','暂时不管黄角朝向，只检查三个颜色是否属于所在角位。如果有一个位置正确的角，把它放右前上，执行角块循环；若没有正确角，先执行一次，再寻找正确角。必要时再做一次，直到四个角位置正确。',"U R U' L' U R' U' L"],['黄色角块朝向','把没朝上的黄角放右前上。保持整个魔方方向不变，重复 R\' D\' R D 直到该角黄色朝上（每次完整做四步）。只转 U 将下一个没朝上的角送到同处，再重复。过程中底层会暂时打乱，务必做完所有角块，最后对齐 U。',"R' D' R D"],['最后的棱块排列','若有一面顶层侧色已对齐中心，把这面放到后面。执行下方 Ua 循环，检查结果；必要时再执行一次，或使用其逆公式。如果没有一面已对齐，先执行一次再观察。最后转 U 对齐侧面，恭喜完成还原！',"R U' R U R U R U' R' U' R2"]]},cfop:{title:'和 CFOP 做朋友',intro:'CFOP 是 Cross → F2L → OLL → PLL。先练顺序与观察，再追求速度。完整 F2L / OLL / PLL 图鉴已收录在公式库。',lessons:[['Cross · 底层十字','将白色十字直接在底面完成，棱块侧色必须对齐中心。打乱后先观察四个白棱在哪，用慢速尝试规划前两条棱。先不计时，逐渐减少多余转动。',''],['F2L · 角棱配对','将一个白角与对应中层棱配成一对，再一起插入正确槽位。先把两块拿到顶层，在空槽上方分离、配对，避免破坏已完成的槽位。公式图鉴中的 41 个局面可逐个演示；不必一次全背。',"U R U' R'"],['OLL · 顶层定向','先学二步 OLL：把黄棱翻成十字，再翻黄角。熟练后逐步扩展到完整 57 个局面。保持白底黄顶，先识别黄块图案，再核对周围贴纸位置。',"R U R' U R U2 R'"],['PLL · 顶层排列','保持顶面黄色，识别侧面同色条、车灯和对块。先学习二步 PLL，再扩展到完整 21 类。公式执行结束后，可能还需要一次 U / U\' / U2 对齐（AUF）。',"R U R' U' R' F R2 U' R' U' R U R' F'"]]},more:{title:'新的好奇心 · 多种玩法',intro:'换一种魔方，也换一种观察方法。这里提供学习方向与关键公式，进一步图解可查看下方官方教程。',lessons:[['二阶 · Ortega 思路','二阶没有中心和棱块。先完成一面（可以暂不对齐侧色），再用 OLL 完成对面朝向，最后 PBL 同时排列上下两层角块。PBL 公式图鉴有 8 个收录局面。判断上下层是相邻换角、对角换角还是无需交换。',"R U R' U R U2 R'"],['四阶 · 降阶法','先完成六个中心，记住颜色相对关系：白黄、红橙、蓝绿。将十二组同色棱配对，把四阶当作三阶还原。遇到单组棱翻转时用 OLL parity；顶层仅两组棱对换时用 PLL parity。请在高阶图鉴查看这两个特殊公式。',''],['Roux · 方块思维','先完成左侧 1×2×3 块，再完成右侧块；用 CMLL 完成顶层角块，最后以 M 与 U 处理剩余六棱（LSE）。本站 CMLL 收录 24 个带公式的局面，适合作为查阅资料，不是完整 CMLL 教程。',"M U M' U2 M U M'"],['金字塔与更高阶','金字塔先调整顶尖和中心，完成一层，再处理最后三条棱。L3E / L4E 图鉴可查阅公式（不提供金字塔动画）。五阶及以上先完成中心与配棱，L2E 图鉴用于最后两组棱的特殊局面。','']]}};
function showCourse(key){const course=courses[key];$('#courseTitle').textContent=course.title;$('#courseContent').innerHTML='';const intro=document.createElement('p');intro.textContent=course.intro;$('#courseContent').append(intro);course.lessons.forEach(([title,desc,alg],i)=>{const lesson=document.createElement('details');lesson.className='lesson';lesson.open=i===0;const summary=document.createElement('summary');summary.textContent=String(i+1).padStart(2,'0')+' / '+title;lesson.append(summary);const p=document.createElement('p');p.textContent=desc;lesson.append(p);if(alg){const f=document.createElement('div');f.className='formula';f.textContent=alg;lesson.append(f);const button=document.createElement('button');button.className='outline small';button.textContent='去练习这个公式 →';button.onclick=()=>{$('#courseDialog').close();$('#puzzle').value='3';size=3;state=createCube(3);history=[];stopSequence();$('#algInput').value=alg;draw();$('#play').scrollIntoView({behavior:'smooth'});toast('点击播放观察公式的转动过程')};lesson.append(button)}const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=!!progress[key+'-'+i];input.onchange=()=>{progress[key+'-'+i]=input.checked;storage.set('progress',progress);if(input.checked)toast('又前进了一小步，真好 ♡')};label.append(input,document.createTextNode(' 这一步，我学会了'));lesson.append(label);$('#courseContent').append(lesson)});const link=document.createElement('p');link.innerHTML='需要更多图解？<a href="https://rubiks.com/solve" target="_blank" rel="noopener" style="text-decoration:underline">查看 Rubik’s 官方教程 ↗</a>';$('#courseContent').append(link);$('#courseDialog').showModal()}
$$('[data-course]').forEach(b=>b.onclick=()=>showCourse(b.dataset.course));$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});
let size=3,state=createCube(),history=[],yaw=-.55,pitch=.5,sequence=[],seqIndex=0,seqInterval=null;
const canvas=$('#cube');function draw(){drawCube(canvas,state,size,yaw,pitch)}function updateSequence(){$('#stepLabel').textContent=sequence.length?seqIndex+' / '+sequence.length+(seqIndex? ' · '+sequence[seqIndex-1]:''):'自由练习';$('#stepBack').disabled=seqIndex===0;$('#stepNext').disabled=seqIndex>=sequence.length;$('#pause').textContent=seqInterval?'暂停':'继续'}function stopSequence(){clearInterval(seqInterval);seqInterval=null;sequence=[];seqIndex=0;updateSequence()}function tick(){if(seqIndex>=sequence.length){clearInterval(seqInterval);seqInterval=null;updateSequence();return}move(state,sequence[seqIndex],size);history.push(sequence[seqIndex]);seqIndex++;draw();updateSequence();if(seqIndex>=sequence.length){clearInterval(seqInterval);seqInterval=null;updateSequence();toast('转完啦 ♡')}}function autoPlay(){if(seqIndex>=sequence.length)return;clearInterval(seqInterval);seqInterval=setInterval(tick,650);updateSequence()}
['R','U','F','L','D','B'].forEach(f=>[f,f+"'"].forEach(t=>{const b=document.createElement('button');b.textContent=t;b.setAttribute('aria-label','转动 '+t);b.onclick=()=>{stopSequence();move(state,t,size);history.push(t);draw()};$('#moves').append(b)}));$('#reset').onclick=()=>{stopSequence();state=createCube(size);history=[];draw();$('#scrambleText').textContent='重新出发，每一步都算数。'};$('#undo').onclick=()=>{if(sequence.length){clearInterval(seqInterval);seqInterval=null;if(seqIndex){seqIndex--;move(state,inverse([sequence[seqIndex]])[0],size);history.pop();draw()}updateSequence();return}if(history.length){move(state,inverse([history.pop()])[0],size);draw()}};$('#puzzle').onchange=()=>{size=Number($('#puzzle').value);$('#reset').click()};$('#scramble').onclick=()=>{stopSequence();state=createCube(size);history=[];const moves=[],faces=['R','U','F','L','D','B'];let last='';for(let i=0;i<(size===2?11:size===3?20:35);i++){let f;do{f=faces[Math.floor(Math.random()*faces.length)]}while(f===last);last=f;const wide=size>3&&Math.random()<.25?'w':'';moves.push(f+wide+['',"'",'2'][Math.floor(Math.random()*3)])}apply(state,moves,size);history=[...moves];$('#scrambleText').textContent=moves.join(' ');draw();toast('新的小挑战准备好了！')};$('#algForm').onsubmit=e=>{e.preventDefault();try{const tokens=parseAlg($('#algInput').value);if(!tokens.length)return toast('先输入一个公式吧');for(const t of tokens)move(createCube(size),t,size);clearInterval(seqInterval);if(sequence.join(' ')!==tokens.join(' ')||seqIndex>=sequence.length){sequence=tokens;seqIndex=0}autoPlay()}catch(err){toast(err.message)}};$('#pause').onclick=()=>{if(seqInterval){clearInterval(seqInterval);seqInterval=null;updateSequence()}else autoPlay()};$('#stepNext').onclick=()=>{clearInterval(seqInterval);seqInterval=null;tick()};$('#stepBack').onclick=()=>$('#undo').click();let dragging=null;canvas.onpointerdown=e=>{dragging=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!dragging)return;yaw+=(e.clientX-dragging[0])*.008;pitch=Math.max(-1.4,Math.min(1.4,pitch+(e.clientY-dragging[1])*.008));dragging=[e.clientX,e.clientY];draw()};canvas.onpointerup=canvas.onpointercancel=()=>dragging=null;draw();updateSequence();
let start=0,running=false,frame;function format(t){return (t/1000).toFixed(2)}function timerFrame(){if(running){$('#timer').textContent=format(performance.now()-start);frame=requestAnimationFrame(timerFrame)}}function toggleTimer(){if(running){const elapsed=performance.now()-start;running=false;cancelAnimationFrame(frame);times.push(elapsed);storage.set('times',times);$('#timer').textContent=format(elapsed);$('#timerStart').textContent='再来一次';renderTimes()}else{running=true;start=performance.now();$('#timerStart').textContent='停止计时';timerFrame()}}function renderTimes(){$('#attempts').textContent=times.length;$('#best').textContent=times.length?format(Math.min(...times))+' s':'—';const last=times.slice(-5).sort((a,b)=>a-b);$('#ao5').textContent=last.length===5?format(last.slice(1,-1).reduce((s,v)=>s+v,0)/3)+' s':'—';$('#history').innerHTML=times.length?times.slice(-20).reverse().map((t,i)=>`<div><span># ${times.length-i}</span><span>${format(t)} s</span></div>`).join(''):'还没有记录，试着开始第一次练习吧。'}$('#timer').onclick=$('#timerStart').onclick=toggleTimer;$('#clearTimes').onclick=()=>{times=[];storage.set('times',times);renderTimes();toast('记录已清空')};renderTimes();document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName)||$$('dialog[open]').length)return;if(e.code==='Space'&&$('#play').getBoundingClientRect().top<innerHeight&&$('#play').getBoundingClientRect().bottom>0){e.preventDefault();toggleTimer()}if(e.key==='/'){e.preventDefault();$('#search').focus();$('#library').scrollIntoView({behavior:'smooth'})}});
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){$$('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}},{rootMargin:'-10% 0px -65% 0px'});['home','learn','library','play'].forEach(id=>observer.observe($('#'+id)));
try{data=await(await fetch('algs.json')).json();data.push({id:'parity-oll',group:'PARITY',name:'OLL Parity',label:'单组棱翻转 · Rw 表示右侧两层',algs:["Rw U2 x Rw U2 Rw U2 Rw' U2 Lw U2 Rw' U2 Rw U2 Rw' U2 Rw'"]},{id:'parity-pll',group:'PARITY',name:'PLL Parity',label:'两组棱对换 · Rw 表示右侧两层',algs:["Rw2 R2 U2 Rw2 R2 Uw2 Rw2 R2 Uw2"]});$('#total').textContent=data.length+' 个收录局面';switchCategory('cfop')}catch{$('#total').textContent='公式暂时无法加载';$('#algGrid').innerHTML='<p class="empty">加载失败，请刷新页面再试。互动练习与教程仍然可用。</p>'}
